const d = require(process.argv[2]);
const t = v => Math.round(v*10); // tenths as int
// half-up rounding on integers: value in 1/1000 units -> tenths
const def = n => { if ([n.corte1,n.corte2,n.corte3].some(x=>x===null)) return null;
  const milli = 3*t(n.corte1)+3*t(n.corte2)+4*t(n.corte3); // units of 1/100
  return Math.floor((milli+5)/10)/10; };
const acum = n => { const w=[3,3,4], c=[n.corte1,n.corte2,n.corte3]; let s=0,ws=0; c.forEach((x,i)=>{if(x!==null){s+=w[i]*t(x);ws+=w[i];}}); return {acum:(s/ws/10).toFixed(3), pesoCalificado: ws*10+'%'}; };
for (const e of d.estudiantes) {
  console.log(`\n${e.id} ${e.nombre} (${e.programaId})`);
  let num=0, cred=0, perdidas=[];
  for (const n of d.notas.filter(x=>x.estudianteId===e.id)) {
    const a = d.asistencia.find(x=>x.estudianteId===e.id && x.codigo===n.codigo);
    const pct = a.inasistencias===null? null : a.inasistencias/a.clasesProgramadas*100;
    const pierdeInas = pct!==null && pct>15;
    let df = def(n); const dfCortes=df;
    if (pierdeInas) df = 0.0;
    const estado = df===null ? 'SIN DEFINITIVA' : (df>=3.0?'aprobada':(pierdeInas?'PERDIDA x inasistencia':'PERDIDA'));
    if (df!==null && df<3.0) perdidas.push(n.asignatura);
    if (df!==null){ num += Math.round(df*10)*n.creditos; cred+=n.creditos; }
    console.log(`  ${n.codigo} ${n.asignatura} cr=${n.creditos} cortes=${n.corte1}/${n.corte2}/${n.corte3} defCortes=${dfCortes} final=${df} inas=${a.inasistencias}/${a.clasesProgramadas} (${pct===null?'null':pct.toFixed(2)+'%'}) limite15=${Math.floor(a.clasesProgramadas*0.15)} max permitidas -> ${estado}${dfCortes===null?' acum='+JSON.stringify(acum(n)):''}`);
  }
  // promedio half-up 2 decimals: num in tenths*cred
  const prom = cred? Math.floor((num*100/ cred + 5)/10)/100 : null; // num/cred tenths -> *10 => thousandths? compute
  const exact = num/10/cred;
  const p2 = Math.floor(num*1000/cred/10 + 0.5)/100; // thousandths
  console.log(`  creditos con definitiva=${cred} creditos matriculados=${d.notas.filter(x=>x.estudianteId===e.id).reduce((s,x)=>s+x.creditos,0)} promedio exacto=${exact} promedio2d=${(Math.round(exact*1000)/1000)} -> half-up=${p2} perdidas=[${perdidas}]`);
}
EOF
