// Hook SessionEnd de Claude Code: copia la transcripcion de la sesion a /logs/sesiones
// (regla lights-out 5) redactando correos y posibles llaves de API.
// Recibe por stdin el JSON del hook: { session_id, transcript_path, ... }
const fs = require("fs");
const path = require("path");

const REDACCIONES = [
  [/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, "[correo-redactado]"],
  [/sk-[A-Za-z0-9_-]{16,}/g, "[llave-redactada]"],
  [/(LLM_API_KEY["'=:\s]+)[^\s"',}]+/g, "$1[llave-redactada]"],
];

function redactar(texto) {
  return REDACCIONES.reduce((acc, [patron, reemplazo]) => acc.replace(patron, reemplazo), texto);
}

let entrada = "";
process.stdin.on("data", (c) => (entrada += c));
process.stdin.on("end", () => {
  try {
    const { session_id, transcript_path } = JSON.parse(entrada);
    if (!transcript_path || !fs.existsSync(transcript_path)) return;
    const destinoDir = path.join(process.env.CLAUDE_PROJECT_DIR || process.cwd(), "logs", "sesiones");
    fs.mkdirSync(destinoDir, { recursive: true });
    const fecha = new Date().toISOString().slice(0, 10);
    const destino = path.join(destinoDir, `${fecha}_${session_id}.jsonl`);
    fs.writeFileSync(destino, redactar(fs.readFileSync(transcript_path, "utf8")));
  } catch (e) {
    process.stderr.write(`exportar-log: ${e.message}\n`);
  }
});

