const fs = require("fs");
const [specPath, skelPath, caPath] = process.argv.slice(2);
const must = (c, m) => { if (!c) throw new Error(m); };
let old = fs.readFileSync(specPath, "utf8");

// 1. Separar la basura de la línea 1 (filas D nuevas pegadas por error)
const start = old.indexOf("# SPEC.md");
must(start > 0, "no hay basura al inicio");
const junk = old.slice(0, start);
old = old.slice(start);
const fixedRows = junk.trim().split(/\|(?=\| D-\d)/).map(r => r.trim().endsWith("|") ? r.trim() : r.trim() + " |");
must(fixedRows.length === 5, "esperaba 5 filas D, hay " + fixedRows.length);

// 2. Cuerpos de las secciones viejas
const section = (heading) => {
  const a = old.indexOf("\n## " + heading);
  must(a >= 0, "falta sección " + heading);
  const bodyStart = old.indexOf("\n", a + 1) + 1;
  const b = old.indexOf("\n## ", bodyStart);
  return old.slice(bodyStart, b < 0 ? undefined : b).trim();
};
const body = {
  CONTRATO: section("4. Contrato de la API").replace("### 4.1 Códigos de respuesta", "#### Códigos de respuesta"),
  FUENTES: section("5. Fuentes de conocimiento"),
  RN: section("6. Reglas de negocio"),
  SEG: section("7. Reglas de seguridad y permisos"),
  COMP: section("8. Comportamiento del asistente"),
  AUDITORIA: section("9. Auditoría"),
  FLUJO: section("10. Diseño de referencia del flujo"),
  DATOS: section("13. Datos de referencia").replace(/\n\nTrampas que las pruebas deben cubrir:[^\n]*/, ""),
  DECISIONES: section("14. Decisiones sobre ambigüedades"),
};
must(!body.DATOS.includes("Trampas"), "Trampas sigue en DATOS");

// 3. Reemplazar filas D viejas por las corregidas
for (const row of fixedRows) {
  const id = row.match(/^\| (D-\d+) \|/)[1];
  const re = new RegExp("^\\| " + id + " \\|.*$", "m");
  must(re.test(body.DECISIONES), "no está " + id);
  body.DECISIONES = body.DECISIONES.replace(re, () => row);
}

// 4. CA: quitar la introducción SMART y las tablas SMART por CA
let ca = fs.readFileSync(caPath, "utf8");
ca = ca.slice(ca.indexOf("### CA-01"));
ca = ca.replace(/\| E \| M \| A \| R \| C \|\n\| --- \| --- \| --- \| --- \| --- \|\n\|[^\n]*\n\n/g, "");
must(!ca.includes("| E | M |"), "quedó una tabla SMART");
body.CA = ca.trim();

// 5. Ensamblar y corregir referencias internas
let out = fs.readFileSync(skelPath, "utf8");
for (const [k, v] of Object.entries(body)) {
  must(out.includes("<<" + k + ">>"), "placeholder " + k);
  out = out.replace("<<" + k + ">>\n", () => v + "\n\n");
}
must(!/<<[A-Z]+>>/.test(out), "placeholder sin reemplazar");
out = out
  .replace("| D-14 | Formato de citas | §5.", "| D-14 | Formato de citas | §11.1.")
  .replace(/con los campos de §9\b/g, "con los campos de §11.3");
fs.writeFileSync(specPath, out);
console.log("ok", out.split("\n").length, "líneas");
EOF
node "$S/compose.js" SPEC.md "$S/skeleton.md" "$S/ca.md" && head -3 SPEC.md && grep -n "^#\{2,3\} " SPEC.md && echo --- && grep -n "§" SPEC.md | grep -v "^.*Evaluación §\|Bienestar §" | cut -c1-140

