// Divide specs/001-asistente-academico/spec.md en SPEC.md (sistema) + spec de la feature 001.
const fs = require("fs");
const path = require("path");
const root = process.argv[2];
const featPath = path.join(root, "specs/001-asistente-academico/spec.md");
const must = (c, m) => { if (!c) throw new Error(m); };

const text = fs.readFileSync(featPath, "utf8");
const lines = text.split("\n");
const find = (h) => { const i = lines.indexOf(h); must(i >= 0, "falta: " + h); return i; };
// Rango [inicio, fin) desde un encabezado hasta el siguiente encabezado del mismo nivel o superior
const until = (start, stops) => {
  let i = start + 1;
  while (i < lines.length && !stops.some((s) => lines[i].startsWith(s))) i++;
  return i;
};
const block = (a, b) => lines.slice(a, b).join("\n").trim();

const i1 = find("## 1. Contexto y objetivo");
const i2 = find("## 2. Alcance");
const i3 = find("## 3. Actores y roles");
const i4 = find("## 4. Requerimientos funcionales");
const i7 = find("## 7. Seguridad y permisos");
const i71 = find("### 7.1 Matriz de acceso");
const i8 = find("## 8. Requerimientos no funcionales");
const i91 = find("### 9.1 Contrato de la API (fijo, no se modifica)");
const i92 = find("### 9.2 Flujo de procesamiento de una pregunta");
const i14 = find("## 14. Decisiones");
const i15 = find("## 15. Trazabilidad de requisitos");

// Contenido que sube a SPEC.md
const contexto = block(i1 + 1, i2);
const actores = block(i3 + 1, i4);
const principioSeg = lines[i7 + 2]; // "La autorización es **código determinista**..."
must(principioSeg.startsWith("La autorización es"), "principio de seguridad no encontrado");
const matriz = block(i71 + 1, i8);
const contrato = block(i91 + 1, i92).split("#### Códigos de respuesta").join("### 3.1 Códigos de respuesta");
const decisiones = block(i14 + 1, i15);

const sistema = `# SPEC.md · TutorFlow, especificación del sistema

| Campo | Valor |
| --- | --- |
| Versión | 1.2 · 2026-11-22 |
| Estado | Borrador para aprobación humana |
| Contenido | Lo transversal del sistema: objetivo, prioridades, actores, contrato, matriz de acceso y decisiones |
| Features | \`specs/<feature-id>/spec.md\` (§5) |
| Escenarios | \`escenarios/<feature-id>/\` |

Cada feature tiene su propia spec, que **extiende** este documento y no repite su contenido.

## 1. Objetivo y prioridades

${contexto}

## 2. Actores y roles

${actores}

## 3. Contrato de la API (fijo, no se modifica)

${contrato}

## 4. Matriz de acceso global

${principioSeg} Cada feature detalla sus reglas SEG y no puede ampliar esta matriz sin aprobación humana.

${matriz}

## 5. Features

