// Actualiza rutas y referencias tras mover specs y escenarios a carpetas por feature.
const fs = require("fs");
const path = require("path");
const root = process.argv[2];
const must = (c, m) => { if (!c) throw new Error(m); };
const edit = (rel, pairs) => {
  const p = path.join(root, rel);
  let s = fs.readFileSync(p, "utf8");
  for (const [a, b] of pairs) {
    must(s.includes(a), rel + " -> no encontré: " + a.slice(0, 70));
    s = s.split(a).join(b);
  }
  fs.writeFileSync(p, s);
};
const F = "specs/001-asistente-academico/spec.md";

// 1. Encabezado con enlace a la spec en cada archivo de escenarios
const escDir = path.join(root, "escenarios/001-asistente-academico");
for (const f of fs.readdirSync(escDir)) {
  const p = path.join(escDir, f);
  const lines = fs.readFileSync(p, "utf8").split("\n");
  must(lines[0].startsWith("# "), f + " sin título");
  lines.splice(1, 0, "", "> Spec: [`" + F + "`](../../" + F + ") · Sistema: [`SPEC.md`](../../SPEC.md)");
  fs.writeFileSync(p, lines.join("\n"));
}

