    must(s.includes(a), rel + " -> no encontré: " + a.slice(0, 80));
    s = s.split(a).join(b);
  }
  fs.writeFileSync(p, s);
};

const COL = "postman/collections/tutorflow";
const ENV = "postman/environments/local.environment.yaml";
const RUN = "postman collection run " + COL + " -e \"" + ENV + "\"";

edit(".claude/agents/qa-calidad.md", [
  [
    "- `tests/postman/`: colección de Postman (`tutorflow.postman_collection.json`, formato v2.1) y entorno local (`local.postman_environment.json`, solo `baseUrl`, sin secretos). Cubre de punta a punta, contra la API levantada y la API simulada real: contrato (200/400/403/405/413), una carpeta por archivo de escenarios con todos los casos de permisos y abuso deterministas, la igualdad del cuerpo 403 (D-07) y los encabezados de seguridad. Cada request lleva el ID `ESC-NNN` en el nombre y aserciones `pm.test` (código, forma del JSON y cadenas prohibidas). Los casos que dependen del texto del LLM se quedan en los evals.",
    "- `" + COL + "/`: colección **v3 de Postman** (un `*.request.yaml` por request; usa las skills `postman:collection-schema-v3` y `postman:variables`) y `" + ENV + "` (solo `baseUrl`, sin secretos). Cubre de punta a punta, contra la API levantada: contrato (200/400/403/405/413), una carpeta por archivo de escenarios con todos los casos de permisos y abuso deterministas, la igualdad del cuerpo 403 (D-07) y los encabezados de seguridad. Cada request lleva su `ESC-NNN` en el nombre y aserciones `pm.test` derivadas de la spec (skill `postman:api-testing`). Los casos que dependen del texto del LLM se quedan en los evals. Valídala con `postman collection lint " + COL + " -f error`.\n- `postman/simulations/`: simulación de la API académica (skill `postman:api-simulation`) para los fallos que la API real no produce: timeout, 5xx, coordinador sin programas o con dos, `programaId` malicioso y asignatura con texto de inyección (ESC-085, ESC-089, ESC-108, ESC-135, ESC-136).\n- Prueba de rendimiento de RNF-01 (skill `postman:performance-testing`): `postman performance run` con runner **local** sobre las peticiones denegadas en el filtro previo y umbral `--pass-if \"less_than(p95, 500)\"`.",
  ],
  [
    "1b. Levanta la API y ejecuta `postman collection run tests/postman/tutorflow.postman_collection.json -e tests/postman/local.postman_environment.json --reporters cli,junit`. Pega la tabla final: 0 aserciones fallidas para aprobar.",
    "1b. Levanta la API y ejecuta `" + RUN + " --output postman-cli-reports` (las colecciones v3 locales solo admiten el reporter `cli`). Pega la tabla final: 0 aserciones fallidas para aprobar. Si la spec tiene un umbral de rendimiento, ejecuta también la prueba de rendimiento.",
  ],
]);

