// Integra el plugin oficial de Postman: rutas v3 en postman/, skills por agente y reglas de nube.
const fs = require("fs");
const path = require("path");
const root = process.argv[2];
const must = (c, m) => { if (!c) throw new Error(m); };
const edit = (rel, pairs) => {
  const p = path.join(root, rel);
  let s = fs.readFileSync(p, "utf8");
  for (const [a, b] of pairs) {
    must(s.includes(a), rel + " -> no encontré: " + a.slice(0, 80));
    s = s.split(a).join(b);
  }
  fs.writeFileSync(p, s);
};

const COL = "postman/collections/tutorflow";
const ENV = "postman/environments/local.environment.yaml";
const RUN = "postman collection run " + COL + " -e \"" + ENV + "\"";

