#!/usr/bin/env node

/* eslint-disable no-console */
/* eslint-disable one-var */

const fileSystem = require('node:fs');
const operatingSystem = require('node:os');
const path = require('node:path');

const POSTMAN_INSTRUCTION =
        'Postman CLI is installed on this device, and can be used for API Engineering work.',
    POSTMAN_INSTRUCTION_START = '<!-- postman-cli:installation:start -->',
    POSTMAN_INSTRUCTION_END = '<!-- postman-cli:installation:end -->',
    POSTMAN_INSTRUCTION_BLOCK = [
        POSTMAN_INSTRUCTION_START,
        POSTMAN_INSTRUCTION,
        POSTMAN_INSTRUCTION_END
    ].join('\n'),
    CLAUDE_PLUGIN_MESSAGE = [
        '',
        'Claude Code users and agents can use the Postman Plugin for Claude Code for full API lifecycle',
        'management including documentation, collections, workspaces, environments, mocks, monitors right',
        'from the repository.',
        '',
        'Install it with:',
        '  `claude plugin marketplace add anthropics/claude-plugins-official`',
        '  `claude plugin install postman@claude-plugins-official`'
    ].join('\n');

/**
 * @typedef {Object} AgentConfiguration
 * @property {string} name - User-facing agent name.
 * @property {string} configurationEnvironmentVariable - Environment override for the configuration root.
 * @property {string} fallbackDirectory - Directory beneath the current user's home directory.
 * @property {string[]} instructionFileNames - Ordered instruction files; the last is the fallback.
 * @property {(context: AgentPostConfigurationContext) => void} [postConfiguration] - Agent follow-up.
 */

/**
 * Selects the first existing instruction file, or the final configured fallback.
 *
 * @param {AgentConfiguration} agentConfiguration - Agent path conventions.
 * @param {string} configurationRoot - Resolved agent configuration root.
 * @returns {string} Absolute instruction-file path.
 */
function resolveInstructionFile (agentConfiguration, configurationRoot) {
    const existingInstructionFileName = agentConfiguration.instructionFileNames.find(
        (instructionFileName) => {
            return fileSystem.existsSync(path.join(configurationRoot, instructionFileName));
        }
    );

    return path.join(
        configurationRoot,
        existingInstructionFileName || agentConfiguration.instructionFileNames[
            agentConfiguration.instructionFileNames.length - 1
        ]
    );
}

