            return fileSystem.existsSync(path.join(configurationRoot, instructionFileName));
        }
    );

    return path.join(
        configurationRoot,
        existingInstructionFileName || agentConfiguration.instructionFileNames[
            agentConfiguration.instructionFileNames.length - 1
        ]
    );
