const fs = require("fs");
const path = require("path");
const root = process.argv[2];
const must = (c, m) => { if (!c) throw new Error(m); };
const read = (f) => fs.readFileSync(path.join(root, f), "utf8");
const write = (f, s) => fs.writeFileSync(path.join(root, f), s);
const replaceLine = (f, startsWith, nueva) => {
  const lines = read(f).split("\n");
  const i = lines.findIndex((l) => l.startsWith(startsWith));
  must(i >= 0, f + " sin línea " + startsWith);
  lines[i] = nueva;
  write(f, lines.join("\n"));
};
const edit = (f, pairs) => {
  let s = read(f);
  for (const [a, b] of pairs) { must(s.includes(a), f + " -> " + a.slice(0, 60)); s = s.split(a).join(b); }
  write(f, s);
};
const F = "specs/001-asistente-academico/spec.md";

edit(F, [
  ["`recursosConsultados` (`datos_basicos` | `notas` | `asistencia` | `programa`), `citas`,",
   "`recursosConsultados` (`datos_basicos` | `notas` | `asistencia` | `programa`), **`datosConsultados`** (una entrada por dato leído: `estudianteId`, `programaId`, `recurso` y, cuando aplica, `asignatura` con su código, p. ej. `{\"estudianteId\":\"EST-001\",\"programaId\":\"ING-SIS\",\"recurso\":\"asistencia\",\"asignatura\":\"BD-203\"}`), `citas`,"],
  ["No se registran valores de notas ni la respuesta completa (Ley 1581, Art. 22; D-13). Nunca se registra la llave. Retención configurable, 90 días por defecto.",
   "No se registran valores (cortes, definitivas, faltas, promedios) ni la respuesta completa (Ley 1581, Art. 22; D-13). Nunca se registra la llave. Retención configurable, 90 días por defecto.\n\n**Persistencia (D-25):** cada evento se escribe en la consola **y** en un archivo JSONL por día (`auditoria-AAAA-MM-DD.jsonl`) en la carpeta `Auditoria:Ruta` (en Docker, el volumen `auditoria` montado en `/app/auditoria`, escribible aunque el contenedor sea de solo lectura). El archivo solo se agrega, nunca se reescribe; si no se puede escribir, la petición no falla y se emite un error en la consola."],
  ["  Escenario: Terceros enmascarados en el registro",
